#!/usr/bin/env bash
# Normalize the compiler-version comment emitted by the pinned protoc 34.1.
#
# protoc-gen-go records protoc's internal version as v7.34.1, while buf's
# pinned generation path records it as (unknown). The compiler marker is not
# part of the generated Go semantics; every other generated byte must remain
# exact. Emit a normalized copy on stdout and fail closed for any unexpected
# generated header shape.
set -euo pipefail

if [[ $# -ne 1 ]]; then
  printf 'usage: %s GENERATED_GO_FILE\n' "$0" >&2
  exit 64
fi

input=$1
if [[ ! -f "$input" || -L "$input" ]]; then
  printf 'generated Go input must be a regular non-symlink file: %s\n' "$input" >&2
  exit 1
fi

expected_version='v7.34.1'
generated_header_count="$(awk '
  $0 ~ /^\/\/ Code generated by protoc-gen-go(-grpc)?\. DO NOT EDIT\.$/ { count++ }
  END { print count + 0 }
' "$input")"
[[ "$generated_header_count" -eq 1 ]]

compiler_marker_count="$(awk -v expected="$expected_version" '
  BEGIN {
    marker = "^// ([-][[:space:]]+)?[[:space:]]*protoc[[:space:]]+(unknown|v[0-9]+\\.[0-9]+\\.[0-9]+)$"
    expected_marker = "^// ([-][[:space:]]+)?[[:space:]]*protoc[[:space:]]+" expected "$"
  }
  $0 ~ marker {
    count++
    if ($0 !~ expected_marker) { unexpected++ }
  }
  END {
    if (count != 1 || unexpected != 0) { exit 1 }
    print count
  }
' "$input")"
[[ "$compiler_marker_count" -eq 1 ]]

sed -E \
  's|(^// ([-][[:space:]]+)?[[:space:]]*protoc[[:space:]]+)v7\.34\.1$|\1(unknown)|' \
  "$input"
